// page/05-inspect.js
// The controls that still need an answer or still fail validation.
// Generated by linkedin/automation/scripts/split-page-helpers.py from 00-context.js.

Object.assign(helpers, {
      // The controls that still have no answer.
      unansweredControls(scope) {
        const root = scope || document;
        const out = [];
        const controls = Array.from(
          root.querySelectorAll('input:not([type="hidden"]), textarea, select'),
        ).filter((element) => helpers.visible(element) || element.type === 'radio' || element.type === 'checkbox');
        for (const element of controls) {
          const type = (element.type || element.tagName || '').toLowerCase();
          const label = helpers.labelText(element) || helpers.groupLabel(element);
          const required = helpers.isRequired(element, label);
          if (type === 'radio') {
            const group = element.closest('fieldset, [role="radiogroup"]');
            const radios = group ? group.querySelectorAll('input[type="radio"]') : [];
            if (!Array.from(radios).some((radio) => radio.checked)) {
              out.push({ label, type: 'radio', id: element.id, options: [], required });
            }
            continue;
          }
          if (type === 'checkbox') {
            if (!element.checked) {
              out.push({ label, type: 'checkbox', id: element.id, options: [], required });
            }
            continue;
          }
          if (!String(element.value || '').trim()) {
            out.push({ label, type, id: element.id, options: [], required });
            continue;
          }
          {
            const problem = helpers.controlError ? helpers.controlError(element) : null;
            const marked =
              element.getAttribute('aria-invalid') === 'true' ||
              (element.validity && !element.validity.valid);
            if ((problem && problem.over) || marked) {
              out.push({
                label,
                type,
                id: element.id,
                options: [],
                required,
                reason: problem && problem.over ? 'answer_too_long' : 'invalid_input',
              });
            }
          }
        }
        return out;
      },
});
